template <bool kIsUrl>
struct Base64Encoding {
    static constexpr usize kRadix = 64;
    static constexpr usize kRadixBits = 6;

    static const std::array<char, 64>& get_chars() noexcept
    {
        static const std::array<char, 64>& cache_ = []() -> auto& {
            static std::array<char, 64> cache_;

            constexpr usize kBigA = 0;
            constexpr usize kLittleA = kBigA + 26;
            constexpr usize kZero = kLittleA + 26;

            for (usize i = 0; i < 26; ++i) {
                cache_[i + kBigA] = 'A' + i;
            }
            for (usize i = 0; i < 26; ++i) {
                cache_[i + kLittleA] = 'a' + i;
            }
            for (usize i = 0; i < 10; ++i) {
                cache_[i + kZero] = '0' + i;
            }
            if constexpr (kIsUrl) {
                cache_[62] = '-';
                cache_[63] = '_';
            } else {
                cache_[62] = '+';
                cache_[63] = '/';
            }

            return cache_;
        }();

        return cache_;
    }
};

template <typename UIntT>
inline char* format_base64(UIntT value, char* buffer, usize len) noexcept
{
    return radix_encode<Base64Encoding<false>>(value, buffer, len);
}

template <typename UIntT>
inline char* format_base64url(UIntT value, char* buffer, usize len) noexcept
{
    return radix_encode<Base64Encoding<true>>(value, buffer, len);
}

}  // namespace batt
